/* EDCL Hybrid AI Assistant v2.0 - interface and orchestration (renderer).
   Privacy model: EDCL records and documents are READ-ONLY and LOCAL. They can be used only by a local model or shown on screen.
   The cloud (optional) receives only a screened public question and public excerpts, decided by the privacy gateway in the main
   process. This file never writes to the EDCL data: it uses its own browser database ("edcl-ai-hybrid") and opens the EDCL
   document store read-only. */
(function(){
'use strict';
const C=window.EDCL_AIH_CORE;if(!C){console.warn('EDCL AI Hybrid: core not loaded');return}
if(window.EDCL_AIH_LOADED)return;window.EDCL_AIH_LOADED=1;
const AI=window.edclAI,{Index,chunkText,tok,detectType,wantsPrevious,splitPages,TYPES,isOld,isPublicDoc}=C;
const host=n=>{try{return(0,eval)(n)}catch(e){return undefined}};
const getD=()=>host('D'),getU=()=>host('U');
const userName=()=>{const u=getU();return u&&u.username||''};
const isOwner=()=>{try{const u=getU(),d=getD();if(!u)return false;if(d&&d.SystemOwner)return u.username===d.SystemOwner;return host('typeof isA')==='function'&&!!host('isA')()}catch(e){return false}};
const pmx=k=>{try{return!!host('pm')(k)}catch(e){return false}};
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rx=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');

/* ================= own storage ================= */
const DBN='edcl-ai-hybrid';let _db=null;
const idb=()=>_db?Promise.resolve(_db):new Promise((ok,no)=>{const r=indexedDB.open(DBN,1);r.onupgradeneeded=()=>{const d=r.result;d.createObjectStore('docs',{keyPath:'id'});const c=d.createObjectStore('chunks',{keyPath:'id'});c.createIndex('docId','docId');d.createObjectStore('settings',{keyPath:'key'});d.createObjectStore('accesslog',{keyPath:'id',autoIncrement:true})};r.onsuccess=()=>{_db=r.result;ok(_db)};r.onerror=()=>no(r.error)});
const tx=async(st,mode,fn)=>{const d=await idb();return new Promise((ok,no)=>{const t=d.transaction(st,mode),s=Array.isArray(st)?st.map(x=>t.objectStore(x)):t.objectStore(st);let out;try{out=fn(s)}catch(e){no(e);return}t.oncomplete=()=>ok(out&&out.result!==undefined?out.result:out);t.onerror=()=>no(t.error);t.onabort=()=>no(t.error)})};
const getAll=st=>idb().then(d=>new Promise((ok,no)=>{const r=d.transaction(st).objectStore(st).getAll();r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)}));
const getSet=async()=>{const r=await getAll('settings'),o={backend:'none',url:'http://localhost:11434',model:'',topk:6,route:'auto',source:'lib',localTools:true,allowTables:[],lastWadaSync:''};for(const x of r)o[x.key]=x.value;return o};
const setSet=(k,v)=>tx('settings','readwrite',s=>{s.put({key:k,value:v})});
const rlog=e=>tx('accesslog','readwrite',s=>{s.add({t:new Date().toISOString(),user:userName(),...e})}).catch(()=>{});
let IDX=null,DOCS=[],APPROVED=new Set(),POLICY=null,NETSET=null;
const reload=async()=>{DOCS=await getAll('docs');const ch=await getAll('chunks');IDX=new Index(ch,DOCS);return IDX};
const loadAI=async()=>{if(!AI)return;try{POLICY=await AI.gw.policy();APPROVED=new Set(POLICY.approved.map(a=>a.sha256))}catch(e){POLICY=null}try{NETSET=await AI.net.settings()}catch(e){NETSET=null}};
const onlineReady=()=>!!(NETSET&&NETSET.online&&NETSET.online.enabled&&NETSET.hasKey);
const pub=d=>isPublicDoc(d,APPROVED);
const EMP_CAT=/^(cert|ev|chk):/;

/* ================= READ-ONLY access to EDCL records ================= */
const roCtx=async()=>{const S=await getSet();return{isOwner:isOwner(),pm:pmx,allow:S.allowTables&&S.allowTables.length?S.allowTables:null}};
const signedIn=()=>!!getU();
/* EDCL documents (host store "edcl_docs"): opened READ-ONLY, and only if the database already exists */
const hostDocs=async()=>{if(!signedIn())return[];try{if(indexedDB.databases){const l=await indexedDB.databases();if(!l.some(x=>x.name==='edcl_docs'))return[]}}catch(e){}
  return new Promise(ok=>{const q=indexedDB.open('edcl_docs');q.onerror=()=>ok([]);q.onsuccess=()=>{const db=q.result;if(!db.objectStoreNames.contains('f')){db.close();return ok([])}try{const g=db.transaction('f','readonly').objectStore('f').getAll();g.onsuccess=()=>{db.close();ok(g.result)};g.onerror=()=>{db.close();ok([])}}catch(e){db.close();ok([])}}})};
const canSeeDoc=f=>{const m=String(f.cat||'').match(EMP_CAT);if(m){const sid=String(f.cat).split(':')[1];try{return!!host('canViewDocs')(sid)}catch(e){return false}}if(f.cat==='archive')return isOwner();return true};
const visibleHostDocs=async()=>(await hostDocs()).filter(canSeeDoc);

/* ================= import ================= */
const sha=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');
const loadJs=src=>new Promise((ok,no)=>{const s=document.createElement('script');s.src=src;s.onload=ok;s.onerror=()=>no(new Error('cannot load '+src));document.head.appendChild(s)});
const readPdf=async(buf,prog)=>{if(!window.pdfjsLib)await loadJs('vendor/pdf.min.js');pdfjsLib.GlobalWorkerOptions.workerSrc='vendor/pdf.worker.min.js';const pdf=await pdfjsLib.getDocument({data:buf.slice()}).promise,pages=[];
  for(let i=1;i<=pdf.numPages;i++){const pg=await pdf.getPage(i),tc=await pg.getTextContent();let s='',y=null;for(const it of tc.items){if(y!==null&&Math.abs(it.transform[5]-y)>2)s+=' ';s+=it.str+(it.hasEOL?' ':'');y=it.transform[5]}pages.push(s);if(prog&&i%10===0)prog(i,pdf.numPages)}return pages};
const readAny=async(name,buf,prog)=>{const n=name.toLowerCase();if(n.endsWith('.pdf'))return await readPdf(buf,prog);const txt=new TextDecoder('utf-8').decode(buf);
  if(/\.html?$/.test(n)){const d=new DOMParser().parseFromString(txt,'text/html');d.querySelectorAll('script,style').forEach(x=>x.remove());return[d.body.textContent||'']}if(/\.(txt|md|csv)$/.test(n))return[txt];throw new Error('unsupported file type')};
const newId=()=>'d'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);
const storeDoc=async(doc,pages)=>{const ch=[];pages.forEach((p,i)=>chunkText(p,i+1).forEach((c,j)=>ch.push({id:doc.id+':'+i+':'+j,docId:doc.id,page:c.page,text:c.text})));await tx(['docs','chunks'],'readwrite',([ds,cs])=>{ds.put(doc);ch.forEach(c=>cs.put(c))});return ch.length};
const putDoc=d=>tx('docs','readwrite',s=>{s.put(d)});
const delDoc=async id=>{await tx(['docs','chunks'],'readwrite',([ds,cs])=>{ds.delete(id);const r=cs.index('docId').openKeyCursor(IDBKeyRange.only(id));r.onsuccess=()=>{const c=r.result;if(c){cs.delete(c.primaryKey);c.continue()}}})};
const importBuf=async(name,buf,meta,prog)=>{const hash=await sha(buf);if(DOCS.some(d=>d.hash===hash))return{skipped:'already in the library'};const pages=await readAny(name,buf,prog),chars=pages.reduce((a,p)=>a+p.length,0);if(chars<200)return{skipped:'no selectable text (scanned PDF)'};
  const doc={id:newId(),name:name.replace(/\.[^.]+$/,''),file:name,type:meta.type&&meta.type!=='Auto'?meta.type:detectType(name,pages[0]),version:meta.version||'',source:meta.source||'manual',added:new Date().toISOString(),pages:pages.length,chars,size:buf.byteLength,hash,...(meta.extra||{})};
  const n=await storeDoc(doc,pages);return{doc,passages:n}};

/* ----- official WADA archive -> library (PUBLIC: current + previous edition of each document) ----- */
let SYNCING=false,SYNCMSG='',NEED_SYNC=true;
const verLabel=(g,v)=>(v.year?String(v.year):'')+(v.published?(v.year?' · ':'')+v.published:'')||'';
const syncWada=async prog=>{if(!AI)throw new Error('WADA synchronisation is available in the desktop application');if(SYNCING)return{busy:true};SYNCING=true;
  try{await reload();const L=await AI.wada.list(),want=new Map();let added=0,updated=0,removed=0;const skipped=[];
    for(const g of L.groups)for(const v of g.versions){if(!v.archived||v.role==='older')continue;if(!/\.pdf(\?|$)/i.test(v.sourceUrl||''))continue;want.set(v.sha256,{g,v})}
    for(const d of DOCS.filter(x=>x.source==='wada')){const w=want.get(d.hash);if(!w){await delDoc(d.id);removed++;continue}const nd={...d,role:w.v.role,family:w.g.key,published:w.v.published||'',version:verLabel(w.g,w.v),url:w.v.sourceUrl||d.url};if(nd.role!==d.role||nd.family!==d.family||nd.version!==d.version){await putDoc(nd);updated++}}
    await reload();
    const todo=[...want.entries()].filter(([h])=>!DOCS.some(d=>d.hash===h)).sort((a,b)=>(a[1].v.role==='current'?0:1)-(b[1].v.role==='current'?0:1));
    for(let i=0;i<todo.length;i++){const[h,w]=todo[i];SYNCMSG=`Reading WADA documents ${i+1}/${todo.length}: ${w.g.label}`;if(prog)prog(SYNCMSG);
      try{const r=await AI.wada.read(w.v.fileId),buf=r.bytes.buffer.slice(r.bytes.byteOffset,r.bytes.byteOffset+r.bytes.byteLength);if(await sha(buf)!==h)throw new Error('checksum mismatch');
        const pages=await readPdf(buf),chars=pages.reduce((a,p)=>a+p.length,0);if(chars<200){skipped.push(w.g.label+' (no selectable text)');continue}
        const doc={id:newId(),name:(w.v.title||w.g.label).replace(/\s*-\s*current download$/i,''),file:r.name,type:detectType((w.v.title||'')+' '+(w.g.label||'')+' '+r.name,pages[0]),version:verLabel(w.g,w.v),source:'wada',role:w.v.role,family:w.g.key,published:w.v.published||'',url:w.v.sourceUrl,wadaFileId:w.v.fileId,added:new Date().toISOString(),pages:pages.length,chars,size:r.size,hash:h};
        await storeDoc(doc,pages);await reload();added++}catch(e){skipped.push(w.g.label+': '+e.message)}}
    await setSet('lastWadaSync',new Date().toISOString());NEED_SYNC=false;return{added,updated,removed,skipped}}finally{SYNCING=false;SYNCMSG=''}};
try{if(AI&&AI.wada.onChanged)AI.wada.onChanged(()=>{NEED_SYNC=true})}catch(e){}

/* ----- public web pages (approved sites) ----- */
const addWeb=async url=>{if(!AI)throw new Error('Internet access is available in the desktop application');await reload();const r=await AI.net.fetch({url}),when=new Date().toISOString();let pages;
  if(r.kind==='pdf'){const buf=r.bytes.buffer.slice(r.bytes.byteOffset,r.bytes.byteOffset+r.bytes.byteLength);pages=await readPdf(buf)}else pages=splitPages(r.text);
  if(pages.reduce((a,p)=>a+p.length,0)<200)throw new Error('The page has too little readable text');
  const prev=DOCS.filter(d=>d.source==='web'&&d.url===r.url).sort((a,b)=>String(b.added).localeCompare(String(a.added)));
  if(prev[0]&&prev[0].hash===r.sha256){await putDoc({...prev[0],fetchedAt:when});await reload();return{unchanged:true}}
  for(const p of prev)if(p.role!=='previous')await putDoc({...p,role:'previous'});for(const o of prev.slice(1))await delDoc(o.id);
  const doc={id:newId(),name:r.title||r.url,file:r.url,type:r.kind==='pdf'?detectType(r.title,pages[0]):'Web',version:when.slice(0,10),source:'web',role:'current',url:r.url,fetchedAt:when,added:when,pages:pages.length,chars:pages.reduce((a,p)=>a+p.length,0),size:r.size,hash:r.sha256};
  await storeDoc(doc,pages);await reload();return{doc,changed:!!prev.length}};

/* ----- EDCL documents -> local library (CONFIDENTIAL: local model only, never cloud) ----- */
const indexHostDocs=async prog=>{await reload();const fs=await visibleHostDocs();let added=0,same=0,skipped=0;
  for(let i=0;i<fs.length;i++){const f=fs[i];if(!/\.(pdf|txt|md|html?|csv)$/i.test(f.name||'')||!f.blob){skipped++;continue}if(prog)prog(`${i+1}/${fs.length} ${f.name}`);
    try{const buf=await f.blob.arrayBuffer();const r=await importBuf(f.name,buf,{source:'edcl',version:f.code||'',extra:{cat:f.cat,hostId:f.id}});if(r.skipped)same++;else{added++;await reload()}}catch(e){skipped++}}
  await rlog({via:'index',tool:'documents',table:'edcl_docs',columns:[],filters:[],rows:added});return{added,same,skipped}};

/* ================= language models ================= */
const localReady=S=>S.backend==='ollama'||S.backend==='openai';
const askLocal=(S,system)=>async(msgs,sys)=>AI.llm.local({backend:S.backend,url:S.url,model:S.model,system:sys||system,messages:msgs});
const fmtHits=hits=>hits.map((h,i)=>`[${i+1}] (${h.doc?h.doc.name:'document'}${h.doc&&h.doc.version?' '+h.doc.version:''}${h.doc&&h.doc.role==='previous'?' [PREVIOUS EDITION - superseded]':h.doc&&h.doc.role==='older'?' [OLDER EDITION - superseded]':h.doc&&h.doc.role==='current'?' [CURRENT EDITION]':''}, page ${h.chunk.page})\n${h.chunk.text}`).join('\n\n');
const LOCAL_SYS='You are the EDCL Technical Documents Assistant for an anti-doping laboratory. Answer ONLY from the numbered excerpts. Cite them as [1], [2]. If the answer is not in the excerpts say so. Never invent requirements, limits, dates or document numbers. Excerpts marked PREVIOUS or OLDER EDITION are superseded: never present them as current; when asked what changed, state both. Answer in the language of the question; be concise. Not an official WADA interpretation.';
const withSiblings=(hits,limit,opts)=>{const out=hits.slice(),seen=new Set(out.map(h=>h.chunk.id));for(const h of hits.slice(0,3)){if(!h.doc||!h.doc.family)continue;const sib=IDX.search(h.chunk.text.slice(0,400),{includePrev:true,limit:12,...opts}).filter(x=>x.doc&&x.doc.family===h.doc.family&&x.doc.id!==h.doc.id&&!seen.has(x.chunk.id)).slice(0,1);for(const x of sib){seen.add(x.chunk.id);out.push(x)}}return out.slice(0,limit)};

/* ================= the hybrid answer flow ================= */
let CHAT=[],TAINTED=false,BUSY=false;
const answerFlow=async(text,opt,S)=>{
  const D=getD(),terms=C.sensitiveTerms(D),scr=AI?await AI.gw.screen({text,terms}):{found:0},cls=C.classify(text,scr.found),incl=opt.prev||wantsPrevious(text),lim=S.topk||6;
  const prevUser=CHAT.filter(m=>m.role==='user').slice(-2,-1)[0],query=tok(text).length<4&&prevUser?prevUser.content+' '+text:text;
  let route=opt.mode==='local'?'local':opt.mode==='cloud'?'cloud':(cls.dataIntent||TAINTED)?'local':(onlineReady()?'cloud':'local'),notes=[];
  if(opt.mode==='auto'&&route==='local'&&onlineReady()){notes.push(TAINTED?'This chat already used confidential EDCL data, so it stays local.':cls.dataIntent?'Routed locally: '+cls.reason:'')}
  const result=async r=>{
    if(r==='cloud'){
      let hits=IDX.search(query,{limit:lim,includePrev:incl,onlyPublic:true,approved:APPROVED});if(incl)hits=withSiblings(hits,lim+3,{onlyPublic:true,approved:APPROVED});
      const ex=hits.map(h=>({docId:h.doc.id,docSha:h.doc.hash,name:h.doc.name,version:h.doc.version,role:h.doc.role,page:h.chunk.page,text:h.chunk.text}));
      const res=await AI.llm.cloud({question:text,excerpts:ex,terms,tainted:TAINTED,web:!!opt.web});
      if(res.blocked)return{blocked:res.reasons};
      return{route:'cloud',text:res.text,hits,webSources:res.sources,gateway:res.gateway,meta:{searches:res.searches,scope:res.scope,reasoning:res.reasoning,model:res.model},evidence:ex.map(x=>x.text).join('\n')}}
    // LOCAL
    let hits=IDX.search(query,{limit:lim,includePrev:incl});if(incl)hits=withSiblings(hits,lim+3,{});
    const conf=hits.some(h=>!pub(h.doc));
    if(!localReady(S))return{route:'local',noModel:true,hits,conf};
    const D2=getD(),ctx=await roCtx();
    if(S.localTools&&(cls.dataIntent||opt.tools)&&signedIn()){
      const search=q=>IDX.search(q,{limit:4,includePrev:incl}).map(x=>({...x,confidential:!pub(x.doc)}));
      const lr=await C.runToolLoop({ask:askLocal(S,''),question:text,library:hits.length?fmtHits(hits):'',env:{D:D2,ctx,search,log:e=>rlog(e)}});
      return{route:'local',text:lr.answer,hits,steps:lr.steps,used:lr.usedData||conf,evidence:fmtHits(hits)+'\n'+lr.evidence}}
    const msgs=[{role:'user',content:`Excerpts:\n${hits.length?fmtHits(hits):'(no excerpt matched)'}\n\nQuestion: ${text}`}];
    const hist=CHAT.slice(-5,-1).filter(m=>!m.err&&m.role).map(m=>({role:m.role,content:m.content}));
    const t=await AI.llm.local({backend:S.backend,url:S.url,model:S.model,system:LOCAL_SYS,messages:[...hist,...msgs]});
    return{route:'local',text:t,hits,used:conf,evidence:fmtHits(hits)}};
  let r=await result(route);
  if(r.blocked&&opt.mode==='auto'&&localReady(S)){notes.push('Not sent to the cloud: '+r.blocked.map(x=>x.text).join(' ')+' It was answered locally instead.');r=await result('local')}
  if(r.blocked)return{role:'assistant',content:'🛡 The privacy gateway did not send this to the cloud.\n'+r.blocked.map(x=>'• '+x.text).join('\n'),err:true,route:'cloud'};
  if(r.used)TAINTED=true;
  const msg={role:'assistant',route:r.route,hits:r.hits||[],notes,steps:r.steps,webSources:r.webSources,gateway:r.gateway,meta:r.meta,conf:!!r.used};
  if(r.noModel){msg.content='No local AI model is connected, so I cannot compose an answer. '+(cls.dataIntent?'For questions about EDCL records use the Data tab (read-only), or connect a local model in Settings. ':'')+'Closest passages in the library:';msg.err=true;msg.hits=(r.hits||[]).slice(0,4);return msg}
  msg.content=String(r.text||'').trim()||'(empty answer)';const g=C.groundingCheck(msg.content,r.evidence||'');if(g.unverified.length)msg.warnings=g.unverified;return msg};

/* ================= interface ================= */
const css=`.aih-t{display:flex;gap:6px;margin-bottom:12px;flex-wrap:wrap}.aih-t button{border:1px solid var(--b,#d6e3dd);background:#fff;padding:7px 12px;border-radius:9px;cursor:pointer;font:inherit}.aih-t button.on{background:var(--n,#0b7a4f);color:#fff;border-color:transparent}
.aih-chat{height:46vh;min-height:260px;overflow:auto;border:1px solid var(--b,#d6e3dd);border-radius:12px;padding:12px;background:#fbfdfc;display:flex;flex-direction:column;gap:10px}
.aih-m{max-width:88%;padding:10px 13px;border-radius:12px;line-height:1.45;white-space:pre-wrap;word-wrap:break-word}.aih-m.u{align-self:flex-end;background:var(--n,#0b7a4f);color:#fff}.aih-m.a{align-self:flex-start;background:#fff;border:1px solid var(--b,#d6e3dd)}
.aih-src{margin-top:8px;font-size:12px;color:var(--m,#5d6f68);white-space:normal}.aih-src div{margin:4px 0;padding:6px 8px;background:#f3f8f6;border-radius:8px}
.aih-in{display:flex;gap:8px;margin-top:10px}.aih-in textarea{flex:1;padding:10px;border:1px solid var(--b,#d6e3dd);border-radius:10px;font:inherit;resize:vertical;min-height:46px}
.aih-note{font-size:12px;color:var(--m,#5d6f68);margin:6px 0}.aih-r{padding:10px 0;border-bottom:1px solid var(--b,#e3ece8)}.aih-r mark{background:#fff0a8;padding:0 1px}
.aih-tag{display:inline-block;font-size:11px;background:#e3f3ec;color:#0f5a3e;border-radius:6px;padding:1px 7px;margin-right:6px}.aih-tag.prev{background:#fff0d6;color:#8a5a00}.aih-tag.cur{background:#dcf5e7;color:#0a6b3d}.aih-tag.web{background:#e2ecff;color:#1f4aa8}.aih-tag.loc{background:#ffeede;color:#8a4a00}.aih-tag.cld{background:#e6f0ff;color:#1f4aa8}.aih-tag.pub{background:#dcf5e7;color:#0a6b3d}.aih-tag.con{background:#ffe1e1;color:#a11}
.aih-warn{background:#fff7e6;border:1px solid #f1d49a;border-radius:10px;padding:8px 12px;font-size:13px;margin:8px 0}.aih-priv{background:#eef7f2;border:1px solid #bfdccd;border-radius:10px;padding:8px 12px;font-size:13px;margin:8px 0}.aih-lock{background:#fff0f0;border:1px solid #efb9b9;border-radius:10px;padding:8px 12px;font-size:13px;margin:8px 0}
.aih-grid{overflow:auto;max-height:50vh;border:1px solid var(--b,#d6e3dd);border-radius:10px}.aih-grid table{border-collapse:collapse;width:100%;font-size:12px}.aih-grid th,.aih-grid td{border-bottom:1px solid #e8efec;padding:5px 8px;text-align:left;white-space:nowrap;max-width:320px;overflow:hidden;text-overflow:ellipsis}.aih-grid th{background:#f3f8f6;position:sticky;top:0}`;
let TAB='ask';
const hd=(t,s)=>{try{return host('head')(t,s)}catch(e){return`<h1>${E(t)}</h1><div class="sub">${E(s)}</div>`}};
const roleTag=d=>d.role==='previous'||d.role==='older'?'<span class="aih-tag prev">previous</span>':d.role==='current'?'<span class="aih-tag cur">current</span>':'';
const srcTag=d=>d.source==='wada'?'<span class="aih-tag">WADA sync</span>':d.source==='web'?'<span class="aih-tag web">web</span>':d.source==='edcl'?'<span class="aih-tag">EDCL doc</span>':'<span class="aih-tag">manual</span>';
const clsTag=d=>pub(d)?'<span class="aih-tag pub">public</span>':'<span class="aih-tag con">confidential</span>';
const snip=(text,q)=>{const ts=[...new Set(tok(q))].filter(t=>t.length>2).slice(0,8);let pos=0;const low=text.toLowerCase();for(const t of ts){const i=low.indexOf(t);if(i>=0){pos=Math.max(0,i-120);break}}let h=E(text.slice(pos,pos+520));if(ts.length)h=h.replace(new RegExp('('+ts.map(t=>rx(E(t))).join('|')+')','gi'),'<mark>$1</mark>');return(pos>0?'… ':'')+h+(pos+520<text.length?' …':'')};
const statusLine=S=>{const n=k=>DOCS.filter(d=>d.source===k).length,mode=localReady(S)?'local model: '+E(S.model||'name not set'):'no local model connected';
  return`<div class="aih-note">Library: <b>${DOCS.length}</b> document(s) (${n('wada')} WADA sync · ${n('web')} web · ${n('edcl')} EDCL documents · ${n('manual')||0} manual) · <b>${IDX?IDX.ch.length:0}</b> passages · ${mode} · cloud AI: <b>${onlineReady()?'ON (public content only, via privacy gateway)':'off'}</b></div>`};
const render=async()=>{const v=document.querySelector('#v');if(!v)return;if(!IDX)await reload();await loadAI();const S=await getSet(),own=isOwner();
  if(!signedIn()){v.innerHTML=hd('AI Assistant','Please sign in.');return}
  if(!['ask','search','data'].includes(TAB)&&!own)TAB='ask';
  const tabs=[['ask','💬 Ask'],['search','🔎 Search'],['data','🗂 EDCL data (read-only)']].concat(own?[['lib','📚 Library'],['net','🌐 Internet'],['priv','🛡 Privacy'],['set','⚙️ Settings']]:[]);
  v.innerHTML=hd('AI Assistant','Hybrid: your records stay local · public WADA / scientific questions can use the cloud through the privacy gateway')+`<style>${css}</style><div class="aih-t">${tabs.map(t=>`<button data-t="${t[0]}" class="${TAB===t[0]?'on':''}">${t[1]}</button>`).join('')}</div><div id="aih-body"></div>`;
  v.querySelector('.aih-t').onclick=e=>{const b=e.target.closest('[data-t]');if(b){TAB=b.dataset.t;render()}};
  ({ask:askTab,search:searchTab,data:dataTab,lib:libTab,net:netTab,priv:privTab,set:setTab}[TAB]||askTab)(v.querySelector('#aih-body'),S);
  const stale=!S.lastWadaSync||Date.now()-new Date(S.lastWadaSync).getTime()>30*60000;
  if(AI&&!SYNCING&&(NEED_SYNC||stale)){NEED_SYNC=false;syncWada(m=>{const n=document.querySelector('#aih-sync');if(n)n.textContent=m}).catch(e=>console.warn('AI WADA sync:',e.message))}};
const msgHtml=m=>{if(m.role==='user')return`<div class="aih-m u">${E(m.content)}</div>`;
  const badge=m.route==='cloud'?'<span class="aih-tag cld">☁ cloud · public content only</span>':'<span class="aih-tag loc">🔒 local</span>';
  const steps=m.steps&&m.steps.length?`<div class="aih-src"><b>Records read (read-only)</b>${m.steps.map(s=>`<div>${s.error?'⚠ '+E(s.tool)+': '+E(s.error):s.tool==='docs'?'📄 library search: '+s.passages+' passage(s)':'🗂 '+E(s.tool)+' <b>'+E(s.table)+'</b>'+(s.columns?' ('+E(s.columns.join(', '))+')':'')+': '+(s.rows!==undefined?s.rows+' of '+s.total+' row(s)':s.total+' row(s)')}</div>`).join('')}</div>`:'';
  const hits=m.hits&&m.hits.length?`<div class="aih-src"><b>Library sources</b>${m.hits.map((x,i)=>`<div><b>[${i+1}]</b> ${x.doc?clsTag(x.doc)+roleTag(x.doc):''}${E(x.doc?x.doc.name:'')}${x.doc&&x.doc.version?' · '+E(x.doc.version):''} · page ${x.chunk.page}<br>${snip(x.chunk.text,'')}</div>`).join('')}</div>`:'';
  const web=m.webSources&&m.webSources.length?`<div class="aih-src"><b>Web sources</b>${m.webSources.map(s=>`<div>🌐 ${E(s.title||s.url)}<br><span style="word-break:break-all">${E(s.url)}</span></div>`).join('')}</div>`:'';
  const gw=m.gateway&&(m.gateway.withheld||m.gateway.redactions)?`<div class="aih-note">🛡 Gateway: ${m.gateway.sent} public passage(s) sent${m.gateway.withheld?', '+m.gateway.withheld+' withheld (not approved for the cloud)':''}${m.gateway.redactions?', '+m.gateway.redactions+' item(s) redacted':''}.</div>`:'';
  const mt=m.meta?`<div class="aih-note">${E(m.meta.model||'')}${m.meta.reasoning==='extended'?' · extended reasoning':''}${m.meta.scope?' · web scope: '+E(m.meta.scope)+' ('+(m.meta.searches||0)+' search(es))':''}</div>`:'';
  const notes=(m.notes||[]).filter(Boolean).map(n=>`<div class="aih-note">ℹ ${E(n)}</div>`).join('');
  const timing=m.responseTimeMs!=null?`<div class="aih-note">Response time: ${(m.responseTimeMs/1000).toFixed(1)} seconds</div>`:'';
  const warn=m.warnings&&m.warnings.length?`<div class="aih-warn">⚠ Not found in the sources shown: <b>${m.warnings.map(E).join(', ')}</b>. Verify these in the official document before relying on them.</div>`:'';
  return`<div class="aih-m a">${badge}${m.conf?'<span class="aih-tag con">confidential data used</span>':''}<br>${E(m.content)}${warn}${steps}${hits}${web}${gw}${mt}${notes}${timing}</div>`};
const askTab=(b,S)=>{const web=onlineReady()&&NETSET.online.webSearch;
  b.innerHTML=(DOCS.length?'':`<div class="aih-warn">The library is empty. ${AI?'It fills automatically from the WADA archive (WADA Updates → check for updates).':''}</div>`)+statusLine(S)+`<div class="aih-note" id="aih-sync">${E(SYNCMSG)}</div>`+
  (TAINTED?'<div class="aih-lock" id="aih-taint">🔒 This chat used confidential EDCL data. It stays local - the cloud is disabled for it. <button class="btn s sm" id="aih-new">Start a new chat</button></div>':'')+
  `<div class="bar" style="margin-bottom:6px"><label>Route <select id="aih-mode"><option value="auto"${S.route==='auto'?' selected':''}>Automatic (recommended)</option><option value="local"${S.route==='local'?' selected':''}>Local only (records + library)</option><option value="cloud"${S.route==='cloud'?' selected':''}${onlineReady()?'':' disabled'}>Cloud (public WADA / science only)${onlineReady()?'':' - not enabled'}</option></select></label>`+
  `<label><input type="checkbox" id="aih-web"${web?'':' disabled'}> search the web (${web?E(NETSET.online.scope):'cloud off'})</label><label><input type="checkbox" id="aih-prev"> include previous editions</label><label><input type="checkbox" id="aih-tools"${S.localTools?' checked':''}> let the local model read EDCL records</label>${AI?'<button class="btn s sm" id="aih-chk">↻ Check WADA now</button>':''}<button class="btn s sm" id="aih-new2">New chat</button></div>`+
  `<div class="aih-chat" id="aih-chat">${CHAT.length?'':'<div class="aih-note">Examples: “What changed between the previous and current TD2027NA?” (public) · “How many staff are authorised for method M1?” (stays local, read-only) · “Review the literature on 19-norandrosterone detection” (scientific, cloud if enabled).</div>'}</div><div class="aih-in"><textarea id="aih-q" placeholder="Type your question… (Enter = send, Shift+Enter = new line)"></textarea><button class="btn" id="aih-go">Send</button></div><div class="aih-note">Answers are NOT an official WADA interpretation. Numbers, dates and codes that are not found in the sources are flagged. Questions and answers are not saved.</div>`;
  const box=b.querySelector('#aih-chat'),draw=()=>{box.innerHTML=CHAT.map(msgHtml).join('')+(BUSY?'<div class="aih-m a">Working…</div>':'');box.scrollTop=box.scrollHeight};draw();
  const reset=()=>{CHAT=[];TAINTED=false;render()};b.querySelector('#aih-new2').onclick=reset;if(b.querySelector('#aih-new'))b.querySelector('#aih-new').onclick=reset;
  b.querySelector('#aih-mode').onchange=async e=>{await setSet('route',e.target.value)};b.querySelector('#aih-tools').onchange=async e=>{await setSet('localTools',e.target.checked)};
  if(b.querySelector('#aih-chk'))b.querySelector('#aih-chk').onclick=async()=>{const n=b.querySelector('#aih-sync');n.textContent='Checking the WADA website…';try{const r=await host('edclDesktop').wada.check();n.textContent=r.status==='failed'?'The WADA check failed - see WADA Updates → Sync History.':'WADA checked. Updating the library…';await AI.wada.sync({});const s=await syncWada(m=>{n.textContent=m});n.textContent=s&&s.busy?'A library update is already running.':`Library updated: ${s.added} added, ${s.updated} relabelled, ${s.removed} removed.`;await reload()}catch(x){n.textContent='Could not check: '+x.message}};
  const send=async()=>{const q=b.querySelector('#aih-q'),text=q.value.trim();if(!text||BUSY)return;const started=Date.now();q.value='';CHAT.push({role:'user',content:text});BUSY=true;draw();
    try{const S2=await getSet(),m=await answerFlow(text,{mode:b.querySelector('#aih-mode').value,web:b.querySelector('#aih-web').checked,prev:b.querySelector('#aih-prev').checked,tools:b.querySelector('#aih-tools').checked},S2);m.responseTimeMs=Date.now()-started;CHAT.push(m);if(TAINTED&&!b.querySelector('#aih-taint')){BUSY=false;render();return}}
    catch(e){CHAT.push({role:'assistant',content:'Error: '+(e.message||e),err:true,hits:[],responseTimeMs:Date.now()-started})}BUSY=false;draw()};
  b.querySelector('#aih-go').onclick=send;b.querySelector('#aih-q').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}};b.querySelector('#aih-q').focus()};
const searchTab=(b,S)=>{b.innerHTML=statusLine(S)+`<div class="bar"><input id="aih-sq" placeholder="Search words, document numbers (TD2027NA)…" style="flex:1;min-width:240px"><select id="aih-st"><option value="">All types</option>${TYPES.map(t=>`<option>${t}</option>`).join('')}</select><label><input type="checkbox" id="aih-sp"> previous editions</label><button class="btn" id="aih-sg">Search</button></div><div id="aih-res"></div>`;
  const run=()=>{const q=b.querySelector('#aih-sq').value,t=b.querySelector('#aih-st').value,h=IDX.search(q,{limit:25,types:t?[t]:null,includePrev:b.querySelector('#aih-sp').checked});b.querySelector('#aih-res').innerHTML=q.trim()?(h.length?h.map(x=>`<div class="aih-r">${x.doc?clsTag(x.doc)+roleTag(x.doc)+srcTag(x.doc):''}<b>${E(x.doc?x.doc.name:'')}</b>${x.doc&&x.doc.version?' · '+E(x.doc.version):''} · page ${x.chunk.page}<div style="margin-top:4px">${snip(x.chunk.text,q)}</div></div>`).join(''):'<div class="aih-note">No matching passage.</div>'):''};
  b.querySelector('#aih-sg').onclick=run;b.querySelector('#aih-sq').onkeydown=e=>{if(e.key==='Enter')run()}};
const dataTab=async(b,S)=>{const ctx=await roCtx(),cat=C.catalog(getD(),ctx),ok=cat.filter(t=>t.allowed),docs=await visibleHostDocs();
  b.innerHTML=`<div class="aih-priv">🔒 Read-only view of the EDCL records you are already allowed to see. Nothing can be changed here, passwords and secrets are never readable, and every read is logged on this PC (table, columns, number of rows - never the values). This data is never sent to the cloud.</div>
  <div class="card"><h3>Tables</h3><div class="bar"><select id="aih-tb">${ok.map(t=>`<option value="${E(t.table)}">${E(t.table)} (${t.rows})</option>`).join('')}</select><label>Rows <input id="aih-lm" type="number" min="1" max="200" value="50" style="width:70px"></label><button class="btn" id="aih-run">Show</button></div><div id="aih-cols" class="bar"></div><div id="aih-flt" class="bar"></div><div class="aih-note" id="aih-info"></div><div class="aih-grid" id="aih-out" hidden></div>${cat.filter(t=>!t.allowed).length?`<div class="aih-note">Not available to you: ${cat.filter(t=>!t.allowed).map(t=>E(t.table)+' ('+E(t.why)+')').join(', ')}</div>`:''}</div>
  <div class="card"><h3>EDCL documents you can access (${docs.length})</h3>${docs.length?`<div class="aih-grid"><table><thead><tr><th>Category</th><th>Name</th><th>Code</th><th>Size</th><th>Date</th><th>In AI library</th></tr></thead><tbody>${docs.slice(0,300).map(f=>`<tr><td>${E(String(f.cat).replace(/:.*/,':…'))}</td><td>${E(f.name)}</td><td>${E(f.code||'')}</td><td>${E(Math.ceil((f.size||0)/1000))} KB</td><td>${E(f.date||'')}</td><td>${DOCS.some(d=>d.hostId===f.id&&d.source==='edcl')?'yes':''}</td></tr>`).join('')}</tbody></table></div><div class="bar" style="margin-top:8px"><button class="btn s" id="aih-ix">Index these documents for the LOCAL assistant</button><span class="aih-note" id="aih-ixm">PDF, text and HTML files. They become <b>confidential</b> library items (local model only).</span></div>`:'<div class="aih-note">No documents.</div>'}</div>`;
  const tb=b.querySelector('#aih-tb');if(!tb)return;const fcols=()=>{const t=ok.find(x=>x.table===tb.value);b.querySelector('#aih-cols').innerHTML='<span class="aih-note">Columns:</span>'+t.columns.map(c=>`<label><input type="checkbox" class="aih-c" value="${E(c)}" checked> ${E(c)}</label>`).join('');b.querySelector('#aih-flt').innerHTML=`<span class="aih-note">Filter:</span><select id="aih-fc"><option value="">(none)</option>${t.columns.map(c=>`<option>${E(c)}</option>`).join('')}</select><select id="aih-fo">${C.OPS.map(o=>`<option>${o}</option>`).join('')}</select><input id="aih-fv" placeholder="value">`};fcols();tb.onchange=fcols;
  b.querySelector('#aih-run').onclick=async()=>{try{const cols=[...b.querySelectorAll('.aih-c')].filter(x=>x.checked).map(x=>x.value),fc=b.querySelector('#aih-fc').value,q={table:tb.value,columns:cols,limit:+b.querySelector('#aih-lm').value||50};if(fc)q.where=[{col:fc,op:b.querySelector('#aih-fo').value,value:b.querySelector('#aih-fv').value}];
    const r=C.queryRO(getD(),q,await roCtx());await rlog({via:'explorer',tool:'query',table:r.table,columns:r.columns,filters:r.filters,rows:r.returned});
    b.querySelector('#aih-info').textContent=`${r.returned} of ${r.total} row(s)${r.truncated?' (limited)':''}`;const o=b.querySelector('#aih-out');o.hidden=false;o.innerHTML=`<table><thead><tr>${r.columns.map(c=>`<th>${E(c)}</th>`).join('')}</tr></thead><tbody>${r.rows.map(x=>`<tr>${r.columns.map(c=>`<td title="${E(x[c])}">${E(x[c]??'')}</td>`).join('')}</tr>`).join('')}</tbody></table>`}catch(e){b.querySelector('#aih-info').textContent=e.message}};
  if(b.querySelector('#aih-ix'))b.querySelector('#aih-ix').onclick=async()=>{const m=b.querySelector('#aih-ixm');m.textContent='Working…';try{const r=await indexHostDocs(x=>{m.textContent=x});m.textContent=`Done: ${r.added} added, ${r.same} already indexed, ${r.skipped} skipped (unsupported type).`;await reload()}catch(e){m.textContent='Failed: '+e.message}}};
const libTab=(b,S)=>{const rows=DOCS.slice().sort((a,c)=>a.name.localeCompare(c.name)||String(c.added).localeCompare(String(a.added)));
  b.innerHTML=`${AI?`<div class="card"><h3>Official WADA documents (automatic, public)</h3><p class="sub">The current and previous edition of every archived WADA document are read into this library automatically.</p><div class="bar"><button class="btn" id="aih-ws">↻ Update from the WADA archive now</button><span class="aih-note" id="aih-wm">${E(SYNCMSG)}</span></div></div>`:''}
  <div class="card"><h3>Add documents by hand</h3><div class="fg"><label>Files (PDF, HTML, TXT)<input type="file" id="aih-f" multiple accept=".pdf,.html,.htm,.txt,.md"></label><label>Type<select id="aih-ty"><option>Auto</option>${TYPES.map(t=>`<option>${t}</option>`).join('')}</select></label><label>Version / date<input id="aih-ver"></label></div><div class="bar"><button class="btn" id="aih-imp">Add to library</button><span class="aih-note" id="aih-pr"></span></div><div class="aih-note">Manual and EDCL documents are <b>confidential</b> (local only) unless you approve them for the cloud below.</div></div>
  <div class="card"><h3>Documents in the library (${DOCS.length})</h3>${DOCS.length?`<div style="overflow:auto"><table class="tbl" style="width:100%"><thead><tr><th>Name</th><th>Source</th><th>Edition</th><th>Class</th><th>Type</th><th>Version</th><th>Pages</th><th></th></tr></thead><tbody>${rows.map(d=>`<tr><td>${E(d.name)}</td><td>${srcTag(d)}</td><td>${roleTag(d)}</td><td>${clsTag(d)}</td><td>${E(d.type)}</td><td>${E(d.version||'')}</td><td>${d.pages}</td><td style="white-space:nowrap">${!pub(d)&&d.source==='manual'?`<button class="btn s sm" data-ap="${E(d.id)}" title="Allow this document's passages to be sent to the cloud AI">Approve for cloud</button> `:''}${d.source==='manual'&&APPROVED.has(d.hash)?`<button class="btn s sm" data-rv="${E(d.id)}">Revoke</button> `:''}${d.source==='wada'?'<span class="aih-note">managed by sync</span>':`<button class="btn d sm" data-del="${E(d.id)}">Remove</button>`}</td></tr>`).join('')}</tbody></table></div>`:'<div class="aih-note">Nothing yet.</div>'}</div>`;
  const pr=b.querySelector('#aih-pr');
  if(b.querySelector('#aih-ws'))b.querySelector('#aih-ws').onclick=async()=>{const m=b.querySelector('#aih-wm');m.textContent='Working…';try{const r=await syncWada(x=>{m.textContent=x});m.textContent=r.busy?'Already running.':`Done: ${r.added} added, ${r.updated} relabelled, ${r.removed} removed${r.skipped.length?', '+r.skipped.length+' skipped':''}.`;await reload();if(!r.busy)setTimeout(render,1000)}catch(e){m.textContent='Failed: '+e.message}};
  b.querySelector('#aih-imp').onclick=async()=>{const fs=[...b.querySelector('#aih-f').files];if(!fs.length)return alert('Choose one or more files first.');const o={type:b.querySelector('#aih-ty').value,version:b.querySelector('#aih-ver').value.trim(),source:'manual'},res=[];
    for(let i=0;i<fs.length;i++){pr.textContent=`(${i+1}/${fs.length}) ${fs[i].name} …`;try{const r=await importBuf(fs[i].name,await fs[i].arrayBuffer(),o,(p,n)=>{pr.textContent=`(${i+1}/${fs.length}) ${fs[i].name}: page ${p}/${n}`});await reload();res.push(fs[i].name+': '+(r.skipped?'skipped - '+r.skipped:'added ('+r.passages+' passages)'))}catch(e){res.push(fs[i].name+': FAILED - '+e.message)}}alert(res.join('\n'));render()};
  b.onclick=async e=>{const del=e.target.closest('[data-del]'),ap=e.target.closest('[data-ap]'),rv=e.target.closest('[data-rv]');
    if(del){const d=DOCS.find(y=>y.id===del.dataset.del);if(d&&confirm('Remove "'+d.name+'" from the AI library?\n(The original is not touched.)')){await delDoc(d.id);await reload();render()}}
    if(ap){const d=DOCS.find(y=>y.id===ap.dataset.ap);if(d&&confirm('Approve "'+d.name+'" for the cloud AI?\n\nParts of this document may be sent to the online AI service when relevant to a public question. Approve only documents that contain NO confidential, personal or proprietary information.\nYour name and the date are recorded.')){try{await AI.gw.approve({authorized:true,user:userName(),sha256:d.hash,label:d.name});render()}catch(x){alert(x.message)}}}
    if(rv){const d=DOCS.find(y=>y.id===rv.dataset.rv);if(d){try{await AI.gw.revoke({authorized:true,user:userName(),sha256:d.hash});render()}catch(x){alert(x.message)}}}}};
const netTab=(b,S)=>{const W=NETSET;if(!AI||!W){b.innerHTML='<div class="card">Internet access is available in the desktop application.</div>';return}
  const webDocs=DOCS.filter(d=>d.source==='web').sort((a,c)=>String(c.fetchedAt).localeCompare(String(a.fetchedAt)));
  b.innerHTML=`<div class="card"><h3>Approved websites</h3><p class="sub">Pages can be fetched from, and the cloud AI may search, these sites (sub-domains included). One per line.</p><div class="fg"><label>Official<textarea id="aih-d1" rows="5" style="width:100%;font:inherit">${E(W.allowedDomains.join('\n'))}</textarea></label><label>Scientific<textarea id="aih-d2" rows="5" style="width:100%;font:inherit">${E(W.scientificDomains.join('\n'))}</textarea></label></div><div class="bar"><button class="btn" id="aih-dsv">Save</button><button class="btn s" id="aih-drs">Restore defaults</button><span class="aih-note" id="aih-dm"></span></div></div>
  <div class="card"><h3>Add a web page or PDF to the library (public)</h3><div class="bar"><input id="aih-url" placeholder="https://…" style="flex:1;min-width:300px"><button class="btn" id="aih-fe">Fetch &amp; add</button></div><div class="aih-note" id="aih-fm">Only https addresses on the approved websites. A changed page becomes <b>current</b> and the old text <b>previous</b>.</div></div>
  <div class="card"><h3>Web pages in the library (${webDocs.length})</h3>${webDocs.length?`<div style="overflow:auto"><table class="tbl" style="width:100%"><thead><tr><th>Title</th><th>Edition</th><th>Fetched</th><th>Address</th><th></th></tr></thead><tbody>${webDocs.map(d=>`<tr><td>${E(d.name)}</td><td>${roleTag(d)}</td><td>${E(String(d.fetchedAt||d.added).slice(0,16).replace('T',' '))}</td><td style="word-break:break-all;max-width:340px">${E(d.url)}</td><td>${isOld(d)?'':`<button class="btn s sm" data-rf="${E(d.id)}">Refresh</button> `}<button class="btn d sm" data-dw="${E(d.id)}">Remove</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="aih-note">None yet.</div>'}</div>`;
  const dm=b.querySelector('#aih-dm'),own={authorized:true,user:userName()},lines=id=>b.querySelector(id).value.split(/\s*[\n,;]+\s*/).filter(Boolean);
  b.querySelector('#aih-dsv').onclick=async()=>{try{NETSET=await AI.net.setSettings({...own,patch:{allowedDomains:lines('#aih-d1'),scientificDomains:lines('#aih-d2')}});dm.textContent='Saved.'}catch(e){dm.textContent=e.message}};
  b.querySelector('#aih-drs').onclick=async()=>{try{NETSET=await AI.net.setSettings({...own,patch:{allowedDomains:W.defaults.allowedDomains,scientificDomains:W.defaults.scientificDomains}});render()}catch(e){dm.textContent=e.message}};
  const one=async u=>{const r=await addWeb(u);return r.unchanged?'unchanged':r.changed?'updated (the earlier text is now "previous")':'added'};
  b.querySelector('#aih-fe').onclick=async()=>{const u=b.querySelector('#aih-url').value.trim();if(!u)return;const m=b.querySelector('#aih-fm');m.textContent='Fetching…';try{m.textContent='Done: '+await one(u)+'.';setTimeout(render,900)}catch(e){m.textContent='Failed: '+e.message}};
  b.onclick=async e=>{const rf=e.target.closest('[data-rf]'),dw=e.target.closest('[data-dw]');if(rf){const d=DOCS.find(x=>x.id===rf.dataset.rf);if(d){try{alert('Page '+await one(d.url)+'.')}catch(x){alert('Refresh failed: '+x.message)}render()}}
    if(dw){const d=DOCS.find(x=>x.id===dw.dataset.dw);if(d&&confirm('Remove this web page (and its previous edition)?')){for(const x of DOCS.filter(y=>y.source==='web'&&y.url===d.url))await delDoc(x.id);await reload();render()}}}};
const privTab=async(b,S)=>{const P=POLICY,cat=C.catalog(getD(),await roCtx()),al=await getAll('accesslog');let gl=[];try{gl=AI?await AI.gw.log(40):[]}catch(e){}
  const acc=al.slice(-40).reverse();
  b.innerHTML=`<div class="aih-priv"><b>How your data is protected</b><br>• EDCL records and documents are <b>read-only</b> for the assistant and are used only on this PC (local model) or shown to you.<br>• The cloud (if enabled) receives only the question you typed - after the gateway screened it for names, staff IDs, user names, e-mails, phone numbers, IP addresses and long numbers - plus <b>public</b> excerpts (official WADA documents, public web pages, documents the System Owner approved).<br>• A chat that used EDCL data is locked to local use. Cloud calls are stateless (no chat history).<br>• Nothing is written to the EDCL database or its Audit Trail by this add-on; its own logs are below.</div>
  <div class="card"><h3>Gateway</h3>${P?`<div class="bar"><label>When a question contains confidential items <select id="aih-gm"><option value="block"${P.mode==='block'?' selected':''}>Block - send nothing (recommended)</option><option value="redact"${P.mode==='redact'?' selected':''}>Redact - replace by placeholders and send</option></select></label><button class="btn" id="aih-gs">Save</button><span class="aih-note" id="aih-gt"></span></div><div class="aih-note">Documents approved for the cloud: ${P.approved.length?P.approved.map(a=>E(a.label||a.sha256.slice(0,10))+' (by '+E(a.by)+', '+E(String(a.at).slice(0,10))+')').join('; '):'none'}</div>`:'<div class="aih-note">Gateway status unavailable (desktop application only).</div>'}</div>
  <div class="card"><h3>Tables the assistant may read</h3><p class="sub">Untick a table to hide it from the assistant and the Data tab for everyone. Credentials and secrets are always hidden.</p><div class="bar" style="flex-wrap:wrap">${cat.map(t=>`<label style="min-width:210px"><input type="checkbox" class="aih-at" value="${E(t.table)}"${(!S.allowTables.length||S.allowTables.includes(t.table))?' checked':''}> ${E(t.table)} <span class="aih-note">(${t.rows}${t.allowed?'':' · restricted: '+E(t.why)})</span></label>`).join('')}</div><div class="bar"><button class="btn" id="aih-as">Save table list</button><span class="aih-note" id="aih-am"></span></div></div>
  <div class="card"><h3>Gateway log (cloud requests, last 40)</h3>${gl.length?`<div class="aih-grid"><table><thead><tr><th>Time</th><th>Event</th><th>Allowed</th><th>Detail</th></tr></thead><tbody>${gl.map(x=>`<tr><td>${E(String(x.t).replace('T',' ').slice(0,19))}</td><td>${E(x.ev)}</td><td>${x.allowed===undefined?'':x.allowed?'sent':'<b style="color:#a11">blocked</b>'}</td><td>${x.ev==='cloud-request'?`excerpts ${x.excerptsSent}/${x.excerptsIn}, withheld ${x.withheld}, redacted ${x.redacted}, found ${E(JSON.stringify(x.found))}, ${E((x.reasons||[]).join(','))}`:E(x.by||x.mode||'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="aih-note">No cloud request yet.</div>'}</div>
  <div class="card"><h3>EDCL data access log (last 40 reads - no values are stored)</h3>${acc.length?`<div class="aih-grid"><table><thead><tr><th>Time</th><th>User</th><th>Via</th><th>Table</th><th>Columns</th><th>Filters</th><th>Rows</th></tr></thead><tbody>${acc.map(x=>`<tr><td>${E(String(x.t).replace('T',' ').slice(0,19))}</td><td>${E(x.user)}</td><td>${E(x.via)}</td><td>${E(x.table)}</td><td>${E((x.columns||[]).join(', '))}</td><td>${E((x.filters||[]).join('; '))}</td><td>${E(x.rows)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="aih-note">No reads yet.</div>'}</div>`;
  if(b.querySelector('#aih-gs'))b.querySelector('#aih-gs').onclick=async()=>{try{await AI.gw.setMode({authorized:true,user:userName(),mode:b.querySelector('#aih-gm').value});b.querySelector('#aih-gt').textContent='Saved.'}catch(e){b.querySelector('#aih-gt').textContent=e.message}};
  b.querySelector('#aih-as').onclick=async()=>{const on=[...b.querySelectorAll('.aih-at')].filter(x=>x.checked).map(x=>x.value);await setSet('allowTables',on.length===cat.length?[]:on);b.querySelector('#aih-am').textContent='Saved.'}};
const setTab=(b,S)=>{const W=NETSET,O=W&&W.online;
  b.innerHTML=`<div class="card"><h3>Local AI model (can use EDCL records - never leaves the laboratory network)</h3><div class="fg"><label>Type<select id="aih-be"><option value="none"${S.backend==='none'?' selected':''}>None</option><option value="ollama"${S.backend==='ollama'?' selected':''}>Ollama</option><option value="openai"${S.backend==='openai'?' selected':''}>LM Studio / OpenAI-compatible</option></select></label><label>Server address<input id="aih-url" value="${E(S.url)}"></label><label>Model name<input id="aih-mo" value="${E(S.model)}"></label><label>Passages per answer<input id="aih-k" type="number" min="3" max="12" value="${+S.topk||6}"></label></div><div class="bar"><button class="btn" id="aih-sv">Save</button><button class="btn s" id="aih-te">Test connection</button><span class="aih-note" id="aih-ts"></span></div><div class="aih-note">The address is checked by the application: only this PC or the laboratory network is accepted.</div></div>
  ${W?`<div class="card"><h3>Cloud AI - Anthropic (optional, off by default; public content only)</h3><div class="aih-warn"><b>What may leave the laboratory:</b> a public question (screened by the gateway) and public excerpts of official documents. <b>Never</b> EDCL records, employee data, EDCL documents or unapproved library documents. Switch on only if the laboratory's data-protection rules allow it.</div>
  <div class="fg"><label>API key<input id="aih-key" type="password" autocomplete="off" placeholder="${W.hasKey?'A key is stored (hidden) - type a new one to replace it':'sk-ant-…'}"></label><label>Model<input id="aih-om" value="${E(O.model)}"></label><label>Web search scope<select id="aih-os"><option value="official"${O.scope==='official'?' selected':''}>Official sites only</option><option value="scientific"${O.scope==='scientific'?' selected':''}>Official + scientific sites</option><option value="open"${O.scope==='open'?' selected':''}${O.allowOpenWeb?'':' disabled'}>Open web${O.allowOpenWeb?'':' (not allowed)'}</option></select></label><label>Searches per question<input id="aih-oms" type="number" min="1" max="10" value="${+O.maxSearches||5}"></label><label>Reasoning<select id="aih-or"><option value="standard"${O.reasoning==='standard'?' selected':''}>Standard</option><option value="extended"${O.reasoning==='extended'?' selected':''}>Extended (slower, deeper)</option></select></label></div>
  <div class="bar"><label><input type="checkbox" id="aih-ows"${O.webSearch?' checked':''}> allow web search</label><label><input type="checkbox" id="aih-oow"${O.allowOpenWeb?' checked':''}> allow <b>open-web</b> search (any website)</label></div>
  <div class="aih-note">${W.secureStorage?'The key is stored encrypted by Windows for this user account and is never shown again.':'<b>Windows secure storage is not available on this PC - the key cannot be stored safely.</b>'}</div>
  <div class="bar"><button class="btn" id="aih-ksv"${W.secureStorage?'':' disabled'}>Store key</button><button class="btn s" id="aih-kcl"${W.hasKey?'':' disabled'}>Delete key</button><button class="btn s" id="aih-osv">Save options</button><button class="btn s" id="aih-ote"${O.enabled?'':' disabled'}>Test</button><span class="aih-note" id="aih-om2"></span></div>
  <div class="bar"><label><input type="checkbox" id="aih-ocon"${O.enabled?' checked':''}${W.hasKey?'':' disabled'}> <b>I approve cloud AI use</b>${O.enabled?' (approved by '+E(O.consentBy)+' on '+E(String(O.consentAt).slice(0,10))+')':''}</label></div></div>`:'<div class="card">Cloud settings are available in the desktop application.</div>'}`;
  const rd=()=>({backend:b.querySelector('#aih-be').value,url:b.querySelector('#aih-url').value.trim(),model:b.querySelector('#aih-mo').value.trim(),topk:+b.querySelector('#aih-k').value});
  b.querySelector('#aih-sv').onclick=async()=>{const n=rd();for(const k in n)await setSet(k,n[k]);alert('Saved.')};
  b.querySelector('#aih-te').onclick=async()=>{const n=rd(),t=b.querySelector('#aih-ts');if(n.backend==='none'){t.textContent='No model selected.';return}t.textContent='Testing…';try{const m=await AI.llm.models({backend:n.backend,url:n.url});t.textContent='Connected ✔ ('+(m.slice(0,5).join(', ')||'no models listed')+')'}catch(e){t.textContent=e.message}};
  if(!W)return;const om=b.querySelector('#aih-om2'),own={authorized:true,user:userName()};
  b.querySelector('#aih-ksv').onclick=async()=>{const k=b.querySelector('#aih-key').value.trim();if(!k)return om.textContent='Type the key first.';try{NETSET=await AI.net.setKey({...own,key:k});render()}catch(e){om.textContent=e.message}};
  b.querySelector('#aih-kcl').onclick=async()=>{if(!confirm('Delete the stored key? Cloud AI will be switched off.'))return;try{NETSET=await AI.net.clearKey(own);render()}catch(e){om.textContent=e.message}};
  b.querySelector('#aih-osv').onclick=async()=>{try{const ow=b.querySelector('#aih-oow').checked;if(ow&&!O.allowOpenWeb&&!confirm('Allow OPEN-WEB search?\n\nThe cloud AI may then read any website for public questions. The questions are still screened by the gateway and no EDCL data is sent, but the pages it reads are not limited to your approved lists.'))return;
    NETSET=await AI.net.setSettings({...own,patch:{online:{allowOpenWeb:ow,model:b.querySelector('#aih-om').value.trim(),scope:b.querySelector('#aih-os').value,maxSearches:+b.querySelector('#aih-oms').value,reasoning:b.querySelector('#aih-or').value,webSearch:b.querySelector('#aih-ows').checked}}});om.textContent='Saved.';render()}catch(e){om.textContent=e.message}};
  b.querySelector('#aih-ocon').onchange=async e=>{const on=e.target.checked;if(on&&!confirm('Approve cloud AI use?\n\nOnly screened public questions and public excerpts can be sent. EDCL records and documents never leave this PC. This approval is recorded with your name and the date.')){e.target.checked=false;return}try{NETSET=await AI.net.setSettings({...own,patch:{online:{enabled:on}}});render()}catch(x){e.target.checked=!on;om.textContent=x.message}};
  b.querySelector('#aih-ote').onclick=async()=>{om.textContent='Testing…';try{const r=await AI.net.test();om.textContent='Connected ✔ ('+r.model+')'}catch(e){om.textContent=e.message}}};

/* ================= hook into the host (no host function is replaced; one route and one menu entry are added) ================= */
const mount=()=>{if(typeof R==='undefined'||typeof navItems!=='function'){console.warn('EDCL AI Hybrid: host application not recognised; not activated');return}
  R.aih=()=>{render().catch(e=>{const v=document.querySelector('#v');if(v)v.innerHTML='<div class="card">AI Assistant error: '+E(e.message)+'</div>'})};
  try{if(typeof NAVIC!=='undefined')NAVIC.aih=NAVIC.news||'news'}catch(e){}
  const base=navItems;navItems=()=>{const a=base().slice();if(a.some(x=>x[0]==='aih'))return a;const i=a.findIndex(x=>x.length===1&&x[0]==='System'),it=['aih','🤖 AI Assistant'];if(i<0)a.push(it);else a.splice(i,0,it);return a};
  idb().then(reload).catch(e=>console.warn('EDCL AI Hybrid storage:',e))};
mount();
window.EDCL_AIH={version:C.VER,log:e=>rlog(e),answerFlow:(t,o,S)=>answerFlow(t,o,S)};
})();
